import React,{useEffect,useMemo,useState} from "react";
import "./style.css";
import logo from "./assets/turu-logo.png";

const API=(import.meta.env.VITE_API_URL||"https://turu-vereinsapp.onrender.com").replace(/\/$/,"");
const NAV=[["home","Startseite"],["news","News"],["club","Verein"],["fans","Fans"],["partners","Partner"],["integration","Integration"]];
const ROLES=[["member","Mitglied"],["player","Spieler"],["trainer","Trainer"],["team_manager","Mannschafts-Manager"],["board","Vorstand"],["admin","Admin"],["superadmin","Superadmin"],["sponsor","Sponsor"],["partner","Partner"]];
const FALLBACK=["1. Mannschaft","U19","U17","U16","U15","U14","U13","U12","U10","U9","U8","U7","U6","Integration"];
const getToken=()=>localStorage.getItem("turu_token")||"";
async function api(path,opts={}){const r=await fetch(API+path,{...opts,headers:{"Content-Type":"application/json",...(getToken()?{Authorization:`Bearer ${getToken()}`}:{})}});const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.error||`HTTP ${r.status}`);return d;}
const arr=x=>Array.isArray(x)?x:[];

async function imageFileToDataUrl(file){
 if(!file)return "";
 if(!file.type.startsWith("image/"))throw new Error("Bitte eine Bilddatei auswählen.");
 if(file.size>8*1024*1024)throw new Error("Das Foto darf maximal 8 MB groß sein.");
 return await new Promise((resolve,reject)=>{
  const reader=new FileReader();
  reader.onerror=()=>reject(new Error("Foto konnte nicht gelesen werden."));
  reader.onload=()=>{
   const img=new Image();
   img.onerror=()=>reject(new Error("Foto konnte nicht verarbeitet werden."));
   img.onload=()=>{
    const max=1400;
    const scale=Math.min(1,max/Math.max(img.width,img.height));
    const canvas=document.createElement("canvas");
    canvas.width=Math.max(1,Math.round(img.width*scale));
    canvas.height=Math.max(1,Math.round(img.height*scale));
    const ctx=canvas.getContext("2d");
    ctx.drawImage(img,0,0,canvas.width,canvas.height);
    resolve(canvas.toDataURL("image/jpeg",0.82));
   };
   img.src=reader.result;
  };
  reader.readAsDataURL(file);
 });
}

const date=x=>x?new Intl.DateTimeFormat("de-DE",{dateStyle:"medium",timeStyle:"short"}).format(new Date(x)):"";
const localDateTimeInput=x=>{if(!x)return "";const d=new Date(x);if(Number.isNaN(d.getTime()))return "";const pad=n=>String(n).padStart(2,"0");return `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}`};
const role=x=>ROLES.find(r=>r[0]===x)?.[1]||x||"Mitglied";

function FupaWidget({widgetId="fp-widget_root-30xM3kVV7xhim2bXpnqKHDjQanA",title="FuPa – 1. Mannschaft"}){
 useEffect(()=>{
  const script=document.createElement("script");
  script.src="https://widget-api.fupa.net/vendor/widget.js?v1";
  script.async=true;
  script.dataset.turuFupaWidget=widgetId;
  document.body.appendChild(script);
  return()=>{try{script.remove()}catch{}};
 },[widgetId]);
 return <section className="panel fupaPanel"><div className="sectionTitle"><h2>{title}</h2></div><div id={widgetId} className="fupaWidgetRoot"><a href="https://www.fupa.net/club/turu-duesseldorf" target="_blank" rel="noopener noreferrer">TuRU Düsseldorf auf FuPa</a></div></section>;
}

function GroupedNavigation({page,menu,user,go,teams,legalPages,canAdmin}){
 const [open,setOpen]=useState(null);
 useEffect(()=>{if(!menu)setOpen(null)},[menu]);
 const allTeams=Array.isArray(teams)&&teams.length?teams:FALLBACK.map((name,id)=>({id:id+1,name}));
 const firstTeam=allTeams.find(t=>String(t.name||"").trim().toLowerCase()==="1. mannschaft")||allTeams[0];
 const juniorTeams=allTeams.filter(t=>t!==firstTeam);
 const boardPage=siteBoardPageFallback();
 const toggle=id=>setOpen(v=>v===id?null:id);
 const itemActive=(ids)=>ids.includes(page);
 return <>
  <button className={page==="home"?"active":""} onClick={()=>go("home")}>Startseite</button>
  <button className={page==="news"?"active":""} onClick={()=>go("news")}>News</button>
  <div className={`navGroup ${open==="club"?"open":""}`}>
   <button className={itemActive(["club","team","teams","history"])?"active navGroupTrigger":"navGroupTrigger"} onClick={()=>{if(window.innerWidth<=820)toggle("club");else go("club")}}>Verein <span>⌄</span></button>
   <div className="navDropdown">
    <button onClick={()=>go("club")}>Verein</button>
    <div className="navSubGroup"><span>Senioren</span><button onClick={()=>firstTeam&&go("team",firstTeam.id)}>1. Mannschaft</button></div>
    <div className="navSubGroup"><span>Junioren</span>{juniorTeams.map(t=><button key={t.id} onClick={()=>go("team",t.id)}>{t.name}</button>)}</div>
    <button onClick={()=>go(boardPage)}>Vorstand</button>
    <button onClick={()=>go("history")}>Geschichte</button>
   </div>
  </div>
  <button className={page==="fans"?"active":""} onClick={()=>go("fans")}>Fans</button>
  <button className={page==="partners"?"active":""} onClick={()=>go("partners")}>Partner</button>
  <button className={page==="integration"?"active":""} onClick={()=>go("integration")}>Integration</button>
  <div className={`navGroup ${open==="legal"?"open":""}`}>
   <button className={page==="legal"?"active navGroupTrigger":"navGroupTrigger"} onClick={()=>{if(window.innerWidth<=820)toggle("legal");else if(legalPages[0])go("legal",legalPages[0].slug)}}>Rechtliches <span>⌄</span></button>
   <div className="navDropdown legalDropdown">{legalPages.map(x=><button key={x.slug} onClick={()=>go("legal",x.slug)}>{x.title}</button>)}</div>
  </div>
  {canAdmin&&<button className={page==="admin"?"active":""} onClick={()=>go("admin")}>Admin</button>}
 </>;
}
function siteBoardPageFallback(){return "club";}
function Notice({text,close}){return text?<div className="notice" onClick={close}>{text} <b>×</b></div>:null;}

