 const [aiDraft,setAiDraft]=useState(null);
 const [pages,setPages]=useState([]),[legalPages,setLegalPages]=useState([]),[editLegal,setEditLegal]=useState(null),[legalForm,setLegalForm]=useState({title:"",body:"",published:true}),[legalAiPrompt,setLegalAiPrompt]=useState(""),[legalAiFacts,setLegalAiFacts]=useState(""),[editPage,setEditPage]=useState(null),[pageForm,setPageForm]=useState({navLabel:"",slug:"",title:"",lead:"",body:"",imageUrl:"",linkUrl:"",navVisible:true,published:true,archived:false,sortOrder:100,homeFeatured:false,socialRequested:false,reviewAt:""});
 const [editMember,setEditMember]=useState(null),[memberForm,setMemberForm]=useState({firstName:"",lastName:"",alias:"",email:"",membershipType:"fan",membershipNumber:"",teamId:"",accountStatus:"active",role:"member"});
 const [newPassword,setNewPassword]=useState("");
