function UserManager({setNotice,current}){
  const [users,setUsers]=useState([]);
  const [selected,setSelected]=useState(null);
  const [rights,setRights]=useState([]);
  const [form,setForm]=useState({firstName:"",lastName:"",alias:"",email:"",password:"",role:"member"});
  const [userMsg,setUserMsg]=useState({title:"",body:"",push:true});
  const [sendingUserMsg,setSendingUserMsg]=useState(false);

  async function load(){
    try{setUsers(arr(await api("/api/admin/users")))}
    catch(e){setNotice(e.message)}
  }
  useEffect(()=>{load()},[]);

  async function create(){
    try{
      await api("/api/admin/users",{method:"POST",body:JSON.stringify(form)});
      setForm({firstName:"",lastName:"",alias:"",email:"",password:"",role:"member"});
      await load();
      setNotice("Benutzer angelegt.")
    }catch(e){setNotice(e.message)}
  }

  async function choose(u){
    setSelected(u);
    try{
      const d=await api(`/api/admin/users/${u.id}/permissions`);
      setRights(arr(d.rights||d.areas))
    }catch{setRights([])}
  }

  async function roleSave(v){
    try{
      const d=await api(`/api/admin/users/${selected.id}/role`,{method:"PATCH",body:JSON.stringify({role:v})});
      setSelected(d.user||{...selected,role:v});
      await load();
      setNotice("Rolle gespeichert.")
    }catch(e){setNotice(e.message)}
  }

  async function rightsSave(){
    try{
      await api(`/api/admin/users/${selected.id}/permissions`,{method:"POST",body:JSON.stringify({areas:rights,rights})});
      setNotice("Berechtigungen gespeichert.")
    }catch(e){setNotice(e.message)}
  }

  async function sendUserMsg(){
    if(!selected||!userMsg.title.trim()||!userMsg.body.trim()){
      return setNotice("Betreff und Nachricht sind erforderlich.")
    }
    try{
      setSendingUserMsg(true);
      await api("/api/admin/communication",{
        method:"POST",
        body:JSON.stringify({
          title:userMsg.title,
          body:userMsg.body,
          audienceType:"user",
          audienceValue:selected.id,
          pushRequested:userMsg.push
        })
      });
      setUserMsg({title:"",body:"",push:true});
      setNotice("Nachricht an den Benutzer gesendet.")
    }catch(e){setNotice(e.message)}
    finally{setSendingUserMsg(false)}
  }

  return <>
    <section className="panel">
      <h2>Benutzer anlegen</h2>
      <div className="formGrid">
        <input value={form.firstName} onChange={e=>setForm({...form,firstName:e.target.value})} placeholder="Vorname"/>
        <input value={form.lastName} onChange={e=>setForm({...form,lastName:e.target.value})} placeholder="Nachname"/>
        <input value={form.alias} onChange={e=>setForm({...form,alias:e.target.value})} placeholder="Alias"/>
        <input type="email" value={form.email} onChange={e=>setForm({...form,email:e.target.value})} placeholder="E-Mail"/>
        <input type="password" value={form.password} onChange={e=>setForm({...form,password:e.target.value})} placeholder="Passwort"/>
        <select value={form.role} onChange={e=>setForm({...form,role:e.target.value})}>
          {ROLES.map(r=><option key={r[0]} value={r[0]}>{r[1]}</option>)}
        </select>
      </div>
      <button onClick={create}>BENUTZER ANLEGEN</button>
    </section>

    {selected&&<>
      <section className="panel">
        <h2>Rechte für {selected.alias||selected.firstName||selected.first_name}</h2>

        {current.role==="superadmin"&&<>
          <select value={selected.role} onChange={e=>roleSave(e.target.value)}>
            {ROLES.map(r=><option key={r[0]} value={r[0]}>{r[1]}</option>)}
          </select>

          <div className="formGrid">
            {["dashboard","pages","news","teams","players","fans","memberships","users","partners","history","club"].map(x=>
              <label className="terms" key={x}>
                <input
                  type="checkbox"
                  checked={rights.includes(x)}
                  onChange={e=>setRights(v=>e.target.checked?[...new Set([...v,x])]:v.filter(a=>a!==x))}
                />
                {x}
              </label>
            )}
          </div>

          <button onClick={rightsSave}>BERECHTIGUNGEN SPEICHERN</button>
        </>}

        <button onClick={async()=>{
          const p=window.prompt("Neues Passwort (mindestens 8 Zeichen):");
          if(!p)return;
          try{
            await api(`/api/admin/users/${selected.id}/password`,{
              method:"POST",
              body:JSON.stringify({password:p})
            });
            setNotice("Passwort wurde zurückgesetzt.")
          }catch(e){setNotice(e.message)}
        }}>
          PASSWORT ZURÜCKSETZEN
        </button>
      </section>

      <section className="panel">
        <h3>Kommunikation</h3>
        <input
          value={userMsg.title}
          onChange={e=>setUserMsg({...userMsg,title:e.target.value})}
          placeholder="Betreff"
        />
        <textarea
          value={userMsg.body}
          onChange={e=>setUserMsg({...userMsg,body:e.target.value})}
          placeholder="Nachricht an diesen Benutzer"
          rows="5"
        />
        <label className="terms">
          <input
            type="checkbox"
            checked={userMsg.push}
            onChange={e=>setUserMsg({...userMsg,push:e.target.checked})}
          />
          Push-Benachrichtigung senden
        </label>
        <button disabled={sendingUserMsg} onClick={sendUserMsg}>
          {sendingUserMsg?"SENDEN…":"NACHRICHT + PUSH SENDEN"}
        </button>
      </section>
    </>}

    {users.map(u=>
      <article className="fanPost" key={u.id}>
        <b>{u.alias||u.firstName||u.first_name}</b>
        <p>{u.email}</p>
        <small>{role(u.role)}</small>
        <button onClick={()=>choose(u)}>RECHTE VERWALTEN</button>
      </article>
    )}
  </>
}

function Modal({fan,onClose,publish}){const [title,setTitle]=useState(""),[body,setBody]=useState(""),[social,setSocial]=useState(false),[pub,setPub]=useState(true),[imageUrl,setImageUrl]=useState(""),[linkUrl,setLinkUrl]=useState(""),[busy,setBusy]=useState(false);async function photo(e){try{setBusy(true);setImageUrl(await imageFileToDataUrl(e.target.files?.[0]))}catch(e){alert(e.message)}finally{setBusy(false)}}return <div className="modalBack"><div className="modal panel"><button className="close" onClick={onClose}>×</button><h2>{fan?"Neuen Fanbeitrag erstellen":"News veröffentlichen"}</h2><input value={title} onChange={e=>setTitle(e.target.value)} placeholder="Titel"/><textarea value={body} onChange={e=>setBody(e.target.value)} placeholder="Dein Beitrag" rows="7"/><label className="uploadField"><span>📷 Foto hinzufügen</span><input type="file" accept="image/*" onChange={photo} disabled={busy}/>{imageUrl&&<img className="uploadPreview" src={imageUrl} alt="Vorschau"/>}</label><input value={linkUrl} onChange={e=>setLinkUrl(e.target.value)} placeholder="Link (optional)"/>{!fan&&<><label className="terms"><input type="checkbox" checked={pub} onChange={e=>setPub(e.target.checked)}/> Sofort veröffentlichen</label><label className="terms"><input type="checkbox" checked={social} onChange={e=>setSocial(e.target.checked)}/> Für Social Media vormerken</label></>}<button disabled={busy} onClick={()=>publish({title,body,fan,social,published:pub,imageUrl,linkUrl})}>{busy?"FOTO WIRD VERARBEITET…":fan?"FANBEITRAG VERÖFFENTLICHEN":pub?"VERÖFFENTLICHEN":"ALS ENTWURF SPEICHERN"}</button></div></div>}

function PWAInstall(){
 const [deferred,setDeferred]=useState(null),[ios,setIos]=useState(false),[visible,setVisible]=useState(false);
 useEffect(()=>{
  const standalone=window.matchMedia?.("(display-mode: standalone)")?.matches||window.navigator.standalone;
  if(standalone)return;
  const isiOS=/iphone|ipad|ipod/i.test(navigator.userAgent);
  setIos(isiOS);
  const handler=e=>{e.preventDefault();setDeferred(e);setVisible(true)};
  window.addEventListener("beforeinstallprompt",handler);
  if(isiOS)setVisible(true);
  return()=>window.removeEventListener("beforeinstallprompt",handler);
 },[]);
 if(!visible)return null;
 const install=async()=>{
  if(ios){alert("Auf dem iPhone: unten auf „Teilen“ tippen und „Zum Home-Bildschirm“ auswählen.");return}
  if(deferred){deferred.prompt();await deferred.userChoice.catch(()=>{});setDeferred(null);setVisible(false);return}
  alert("Bitte im Browser-Menü „App installieren“ bzw. „Zum Startbildschirm hinzufügen“ auswählen.");
 };
 return <button className="pwaInstallButton" onClick={install}>📱 APP INSTALLIEREN</button>;
}

