 useEffect(()=>{if("serviceWorker" in navigator){window.addEventListener("load",()=>navigator.serviceWorker.register("/sw.js").catch(()=>{}))}},[]);const [page,setPage]=useState("home"),[team,setTeam]=useState(null),[menu,setMenu]=useState(false),[teams,setTeams]=useState([]),[players,setPlayers]=useState([]),[posts,setPosts]=useState([]),[sitePages,setSitePages]=useState([]),[fans,setFans]=useState([]),[vote,setVote]=useState(null),[matches,setMatches]=useState([]),[events,setEvents]=useState([]),[sponsors,setSponsors]=useState([]),[vouchers,setVouchers]=useState([]),[search,setSearch]=useState(""),[notice,setNotice]=useState(""),[modal,setModal]=useState(false),[legalPages,setLegalPages]=useState([]),[requestedPage,setRequestedPage]=useState(null),[requestedLegal,setRequestedLegal]=useState(null),[articleDetail,setArticleDetail]=useState(null),[unreadCount,setUnreadCount]=useState(0),[user,setUser]=useState(()=>{try{return JSON.parse(localStorage.getItem("turu_user"))}catch{return null}});
 useEffect(()=>{if(!user){setUnreadCount(0);return}const refresh=()=>api("/api/me/messages/unread-count").then(d=>setUnreadCount(Number(d.count||0))).catch(()=>{});refresh();const timer=setInterval(refresh,30000);return()=>clearInterval(timer)},[user]);
 async function load(){const r=await Promise.allSettled([api("/api/teams"),api("/api/players"),api("/api/posts"),api("/api/pages"),api("/api/fans/posts"),api("/api/fans/vote"),api("/api/matches"),api("/api/events"),api("/api/sponsors"),api("/api/vouchers"),api("/api/legal")]);const v=(i,d)=>r[i].status==="fulfilled"?r[i].value:d;setTeams(arr(v(0,[])));setPlayers(arr(v(1,[])));setPosts(arr(v(2,[])));setSitePages(arr(v(3,[])));setFans(arr(v(4,[])));setVote(v(5,null));setMatches(arr(v(6,[])));setEvents(arr(v(7,[])));setSponsors(arr(v(8,[])));setVouchers(arr(v(9,[])));setLegalPages(arr(v(10,[])))}useEffect(()=>{load()},[]);useEffect(()=>{if(getToken())api("/api/auth/me").then(d=>{setUser(d.user);localStorage.setItem("turu_user",JSON.stringify(d.user))}).catch(()=>{})},[]);
